    event: React.MouseEvent<HTMLDivElement, MouseEvent>,
    noteId: string = ''
  ) => {
    event.preventDefault()
    const clicked = event.target
    const RIGHT_CLICK = 2

    // Make sure we aren't getting any null values .. any element clicked should be a sub-class of element
    if (!clicked) return

