                      <FolderIcon size={12} className="context-menu-action" />
                      {noteCategory?.name}
                    </>
                  ) : (
                    <>
                      <Book size={12} className="context-menu-action" />
                      Notes
                    </>
                  )}
                </div>
              )}
              {optionsId === note.id && !isDraftNote(note) && (
